package com.jian.scrcpy.media;
import com.jian.scrcpy.protocol.*;import io.netty.channel.*;import io.netty.util.ReferenceCountUtil;import org.bytedeco.ffmpeg.avcodec.*;import org.bytedeco.ffmpeg.avutil.*;import org.bytedeco.javacpp.*;import java.util.function.Consumer;
import static org.bytedeco.ffmpeg.global.avcodec.*;import static org.bytedeco.ffmpeg.global.avutil.*;
public final class FfmpegAudioDecoder extends SimpleChannelInboundHandler<MediaMessage> implements AutoCloseable{
 private final Consumer<AudioFrame> sink;private AVCodecContext ctx;private AVFrame frame;private AVPacket packet;private CodecId codec;
 public FfmpegAudioDecoder(Consumer<AudioFrame>s){super(false);sink=s;}
 private int avId(CodecId c){return switch(c){case OPUS->AV_CODEC_ID_OPUS;case AAC->AV_CODEC_ID_AAC;case FLAC->AV_CODEC_ID_FLAC;default->throw new IllegalArgumentException("Not audio: "+c);};}
 private void init(CodecId c){codec=c;AVCodec dec=avcodec_find_decoder(avId(c));if(dec==null)throw new IllegalStateException("decoder unavailable "+c);ctx=avcodec_alloc_context3(dec);if(ctx==null||avcodec_open2(ctx,dec,(AVDictionary)null)<0)throw new IllegalStateException("cannot open "+c);frame=av_frame_alloc();packet=av_packet_alloc();}
 protected void channelRead0(ChannelHandlerContext ch,MediaMessage m){if(m instanceof MediaMessage.Codec c){init(c.codec());return;}if(!(m instanceof MediaMessage.Packet p))return;try{if(p.config())return;byte[] b=new byte[p.data().readableBytes()];p.data().getBytes(p.data().readerIndex(),b);try(BytePointer bp=new BytePointer(b)){av_packet_unref(packet);packet.data(bp).size(b.length).pts(p.pts());if(avcodec_send_packet(ctx,packet)<0)return;while(avcodec_receive_frame(ctx,frame)>=0){int channels=frame.ch_layout().nb_channels();int samples=frame.nb_samples();if(frame.format()!=AV_SAMPLE_FMT_FLT)continue;FloatPointer fp=new FloatPointer(frame.data(0));short[] pcm=new short[samples*channels];for(int i=0;i<pcm.length;i++){float v=Math.max(-1f,Math.min(1f,fp.get(i)));pcm[i]=(short)Math.round(v*32767f);}sink.accept(new AudioFrame(frame.sample_rate(),channels,pcm,p.pts()));}}}finally{ReferenceCountUtil.release(p.data());}}
 public void close(){if(packet!=null)av_packet_free(packet);if(frame!=null)av_frame_free(frame);if(ctx!=null)avcodec_free_context(ctx);}
}